
use std::sync::{Mutex, LazyLock};
use std::collections::HashMap;
use chacha20poly1305::{ChaCha20Poly1305, Key, Nonce, KeyInit, aead::Aead};
use base64::{Engine as _, engine::general_purpose::STANDARD as B64};
#[derive(Clone)] struct SecretEntry { secret: String, created_at: u64, expires_at: Option<u64>, revoked: bool, }
struct KeyRing { current_version: u64, secrets: HashMap<u64, SecretEntry>, rotation_interval_secs: Option<u64>, expiry_secs: Option<u64>, last_rotation: u64, }
static KEYRING: LazyLock<Mutex<KeyRing>>=LazyLock::new(|| Mutex::new(KeyRing{ current_version: 1, secrets: HashMap::new(), rotation_interval_secs: None, expiry_secs: Some(86400), last_rotation: now_secs(), }));
fn now_secs()->u64{ std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs() }
fn derive_master_key(secret:&str)->Key{ *Key::from_slice(blake3::hash(secret.as_bytes()).as_bytes()) }
#[tauri::command] pub fn crypto_set_secret(secret:String)->String{ let mut ring=KEYRING.lock().unwrap(); ring.secrets.insert(ring.current_version, SecretEntry{ secret: secret.clone(), created_at: now_secs(), expires_at: None, revoked: false }); ring.last_rotation=now_secs(); let h=blake3::hash(secret.as_bytes()).to_hex().to_string(); format!("v{} set {}", ring.current_version, &h[..12]) }
#[tauri::command] pub fn crypto_has_secret()->bool{ !KEYRING.lock().unwrap().secrets.is_empty() }
#[tauri::command] pub fn crypto_current_version()->u64{ KEYRING.lock().unwrap().current_version }
#[tauri::command] pub fn crypto_list_versions()->Vec<serde_json::Value>{ let ring=KEYRING.lock().unwrap(); let now=now_secs(); ring.secrets.iter().map(|(v,e)| serde_json::json!({"version": v, "created_at": e.created_at, "expires_at": e.expires_at, "revoked": e.revoked, "expired": e.expires_at.map(|exp| now>exp).unwrap_or(false), "age_secs": now.saturating_sub(e.created_at)})).collect() }
#[tauri::command] pub fn crypto_rotate_secret(new_secret:String)->String{ let mut ring=KEYRING.lock().unwrap(); let old_ver=ring.current_version; if let Some(entry)=ring.secrets.get_mut(&old_ver){ if let Some(expiry)=ring.expiry_secs{ entry.expires_at=Some(now_secs()+expiry); } } ring.current_version+=1; ring.secrets.insert(ring.current_version, SecretEntry{ secret: new_secret.clone(), created_at: now_secs(), expires_at: None, revoked: false }); ring.last_rotation=now_secs(); let h=blake3::hash(new_secret.as_bytes()).to_hex().to_string(); format!("rotated v{}->v{} {}", old_ver, ring.current_version, &h[..12]) }
#[tauri::command] pub fn crypto_set_rotation_schedule(interval_secs:u64, expiry_secs:u64)->String{ let mut ring=KEYRING.lock().unwrap(); ring.rotation_interval_secs=Some(interval_secs); ring.expiry_secs=Some(expiry_secs); format!("auto every {}s expiry {}s", interval_secs, expiry_secs) }
#[tauri::command] pub fn crypto_check_auto_rotate()->Option<String>{ let mut ring=KEYRING.lock().unwrap(); if let Some(interval)=ring.rotation_interval_secs{ let elapsed=now_secs().saturating_sub(ring.last_rotation); if elapsed>=interval{ let new_secret=blake3::hash(format!("auto-{}-{}", now_secs(), ring.current_version).as_bytes()).to_hex().to_string(); let old_ver=ring.current_version; if let Some(entry)=ring.secrets.get_mut(&old_ver){ entry.expires_at=Some(now_secs()+ring.expiry_secs.unwrap_or(86400)); } ring.current_version+=1; ring.secrets.insert(ring.current_version, SecretEntry{ secret: new_secret.clone(), created_at: now_secs(), expires_at: None, revoked: false }); ring.last_rotation=now_secs(); return Some(format!("auto rotated to v{} elapsed {}", ring.current_version, elapsed)); } } None }
#[tauri::command] pub fn crypto_encrypt(plaintext:String)->Result<String,String>{ let ring=KEYRING.lock().unwrap(); let secret=ring.secrets.get(&ring.current_version).ok_or("no secret")?.secret.clone(); drop(ring); let key=derive_master_key(&secret); let cipher=ChaCha20Poly1305::new(&key); let mut nb=[0u8;12]; use rand::RngCore; rand::thread_rng().fill_bytes(&mut nb); let nonce=Nonce::from_slice(&nb); let ct=cipher.encrypt(nonce, plaintext.as_bytes()).map_err(|e| e.to_string())?; let mut comb=Vec::new(); comb.extend_from_slice(&nb); comb.extend_from_slice(&ct); Ok(B64.encode(comb)) }
#[tauri::command] pub fn crypto_decrypt(ciphertext:String)->Result<String,String>{ let ring=KEYRING.lock().unwrap(); let secret=ring.secrets.get(&ring.current_version).ok_or("no secret")?.secret.clone(); drop(ring); let key=derive_master_key(&secret); let cipher=ChaCha20Poly1305::new(&key); let comb=B64.decode(ciphertext).map_err(|e| e.to_string())?; let (nb,ct)=comb.split_at(12); let nonce=Nonce::from_slice(nb); let dec=cipher.decrypt(nonce, ct).map_err(|e| e.to_string())?; Ok(String::from_utf8(dec).map_err(|e| e.to_string())?) }
